<?php $items = $templates; ?>
<section class="mt-7"><div class="flex items-center justify-between"><div><h2 class="text-xl font-extrabold">Templates</h2><p class="text-sm text-[#78908c]">Create and manage reusable email templates.</p></div><a href="<?= workspace_url('templates/new') ?>" class="btn btn-primary">New template</a></div><div class="mt-6 grid gap-5 md:grid-cols-2 xl:grid-cols-3"><?php foreach ($items as $template): ?><article class="card p-6"><div class="flex items-start justify-between"><span class="grid h-11 w-11 place-items-center rounded-xl bg-[#daf2eb] text-mint"><i data-lucide="layout-template" class="h-5"></i></span><span class="rounded-full bg-[#e7f2ef] px-2 py-1 text-xs font-bold text-[#28775f]"><?= esc($template['category']) ?></span></div><h3 class="mt-5 font-extrabold"><?= esc($template['name']) ?></h3><p class="mt-4 text-sm text-[#78908c]">Created <?= date('M j, Y', strtotime($template['created_at'] ?? now())) ?></p><div class="mt-6 flex gap-2"><a href="<?= workspace_url('templates/'.$template['id'].'/edit') ?>" class="btn btn-secondary">Edit</a><form action="<?= workspace_url('templates/'.$template['id'].'/delete') ?>" method="post" onsubmit="return confirm('Delete this template?');" class="inline"><button class="btn btn-soft">Delete</button><?= csrf_field() ?></form></div></article><?php endforeach ?></div></section>
